#include "code_scan.h"
#include "checks_buf.h"
int check_static_buffer(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_ID&&(f->tokens[i+1].type==TK_LBRACK&&f->tokens[i+2].type==TK_NUMBER&&f->tokens[i+3].type==TK_RBRACK)){long long sz=f->tokens[i+2].val;if(sz>4096){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_BUFFER;out->code=8001;snprintf(out->msg,sizeof(out->msg),"Large static buffer: %s[%lld] on stack",f->tokens[i].text,sz);snprintf(out->suggestion,sizeof(out->suggestion),"Use heap allocation for large buffers");}}}}return cnt;}
int check_dynamic_buffer(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"malloc")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_NUMBER){long long sz=f->tokens[j].val;if(sz<1||sz>1073741824){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_BUFFER;out->code=8002;snprintf(out->msg,sizeof(out->msg),"Suspicious allocation size: %lld bytes",sz);}}}}}return cnt;}
int check_array_index(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_LBRACK&&f->tokens[i+1].type==TK_NUMBER&&f->tokens[i+2].type==TK_RBRACK){long long idx=f->tokens[i+1].val;if(idx<0){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_BUFFER;out->code=8003;snprintf(out->msg,sizeof(out->msg),"Negative array index: %lld",idx);}}if(idx>1048576){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_BUFFER;out->code=8003;snprintf(out->msg,sizeof(out->msg),"Very large array index: %lld - may be out of bounds",idx);}}}}return cnt;}
int check_fixed_buffer(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens;i++){if(f->tokens[i].type==TK_NUMBER&&f->tokens[i].val>0&&f->tokens[i].val<=256){if(i>0&&f->tokens[i-1].type==TK_LBRACK){if(i+1<f->ntokens&&f->tokens[i+1].type==TK_RBRACK){cnt++;}}}}if(cnt>20&&out){out->sev=SEV_INFO;out->cat=CAT_BUFFER;out->code=8004;snprintf(out->msg,sizeof(out->msg),"Many fixed-size buffers (%d) - consider dynamic sizing",cnt);}return cnt>20?1:0;}
