int check_unsafe_scanf(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-2;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"scanf")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_STRING){const char*fmt=f->tokens[j].text;if(strstr(fmt,"%s")||strstr(fmt,"%[^")){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_BUFFER;out->code=8013;snprintf(out->msg,sizeof(out->msg),"scanf with %%s without width limit");snprintf(out->suggestion,sizeof(out->suggestion),"Use %%<width>s to limit input size");}}}}}return cnt;}
