int check_read_beyond(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-4;i++){if(f->tokens[i].type==TK_ID&&f->tokens[i+1].type==TK_LBRACK&&f->tokens[i+2].type==TK_NUMBER){long long idx=f->tokens[i+2].val;int j=i+3;if(j<f->ntokens&&f->tokens[j].type==TK_RBRACK){for(int k=i-1;k>=0&&k>i-10;k--){if(f->tokens[k].type==TK_LBRACK&&k>0&&f->tokens[k-1].type==TK_NUMBER){long long sz=f->tokens[k-1].val;if(idx>=sz){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_ERROR;out->cat=CAT_BUFFER;out->code=8016;snprintf(out->msg,sizeof(out->msg),"Read beyond bounds: index %lld >= size %lld",idx,sz);}}}}}}}return cnt;}
