int check_unsafe_realloc(SourceFile*f,Project*p,Issue*out){int cnt=0;for(int i=0;i<f->ntokens-3;i++){if(f->tokens[i].type==TK_ID&&strcmp(f->tokens[i].text,"realloc")==0){int j=i+2;if(j<f->ntokens&&f->tokens[j].type==TK_NUMBER){long long sz=f->tokens[j].val;if(sz<1){cnt++;if(cnt==1&&out){LOC_TOK(out,f,i);out->sev=SEV_WARNING;out->cat=CAT_BUFFER;out->code=8018;snprintf(out->msg,sizeof(out->msg),"realloc with suspicious size %lld",sz);}}}int k=i+1;int has_temp=0;while(k<f->ntokens&&k<i+15){if(f->tokens[k].type==TK_ID){if(k+1<f->ntokens&&f->tokens[k+1].type==TK_EQ)has_temp=1;break;}k++;}if(!has_temp){cnt++;if(cnt==1&&out){out->sev=SEV_WARNING;out->cat=CAT_BUFFER;out->code=8018;snprintf(out->msg,sizeof(out->msg),"realloc without temporary - may leak memory on failure");}}}}return cnt;}
